    char *error_message;
    struct { void *addr; size_t sz; } mapped;
};

static bool lexeme_buffer_consume(struct lexeme_ring_buffer *buf, struct lexeme **lexeme) {
    if (lexeme_ring_buffer_empty(buf)) return false;
    *lexeme = lexeme_ring_buffer_get_ptr(buf);
    return true;
}
static bool lexeme_buffer_emit(struct lexeme_ring_buffer *buf, struct lexeme *lexeme) {
    if (lexeme_ring_buffer_full(buf)) return false;
    lexeme_ring_buffer_put(buf, lexeme);
    return true;
}
static void emit_lexeme(struct lexer *lexer, struct lexeme *lexeme) {
    if (!lexeme_buffer_emit(&lexer->buffer, lexeme)) return;
    lexer->start = lexer->pos;
}
static void emit(struct lexer *lexer, enum lexeme_type type) {
    struct lexeme lexeme = { .type = type, .value = { .value = lexer->start, .len = (size_t)(lexer->pos - lexer->start) } };
    emit_lexeme(lexer, &lexeme);
}
static int next(struct lexer *lexer) {
    if (lexer->pos >= lexer->end) { lexer->pos = lexer->end + 1; return '\0'; }
    int r = *lexer->pos; lexer->pos++;
    if (r == '\n') lexer->cur_line++;
    return r;
}
static void ignore(struct lexer *lexer) { lexer->start = lexer->pos; }
static void advance_n(struct lexer *lexer, size_t n) { lexer->pos += n; ignore(lexer); }
static void backup(struct lexer *lexer) { lexer->pos--; if (*lexer->pos == '\n') lexer->cur_line--; }
static int peek(struct lexer *lexer) { int chr = next(lexer); backup(lexer); return chr; }
static void *lex_config(struct lexer *lexer);
static void *lex_variable(struct lexer *lexer);
static bool isstring(int chr) { return chr && !isspace(chr) && chr != '=' && chr != '#'; }

