    int chr;
    do {
        chr = next(lexer);
        if (chr == '$' && peek(lexer) == '{') { backup(lexer); emit(lexer, LEXEME_STRING); advance_n(lexer, strlen("{")); return lex_variable; }
    } while (isstring(chr));
    backup(lexer); emit(lexer, LEXEME_STRING); return lex_config;
}

static void *lex_error(struct lexer *lexer, const char *msg) {
    struct lexeme lexeme = { .type = LEXEME_ERROR, .value = { .value = msg, .len = strlen(msg) } };
    emit_lexeme(lexer, &lexeme); return NULL;
}

static void *lex_multiline_string(struct lexer *lexer) {
    char *end = (peek(lexer) == '"') ? "\"\"\"" : "'''";
    advance_n(lexer, strlen("'''") - 1);
    do {
        if (!strncmp(lexer->pos, end, 3)) {
            emit(lexer, LEXEME_STRING);
            lexer->pos += 3;
            return lex_config;
        }
    } while (next(lexer) != '\0');
    return lex_error(lexer, "EOF while scanning multiline string");
}

static bool isvariable(int chr) { return isalpha(chr) || chr == '_'; }

static void *lex_variable_default(struct lexer *lexer) {
    while (next(lexer) != '}');
    backup(lexer); emit(lexer, LEXEME_STRING); advance_n(lexer, strlen("}")); return lex_config;
