static void *lex_variable(struct lexer *lexer) {
    int chr;
    advance_n(lexer, strlen("${") - 1);
    do {
        chr = next(lexer);
        if (chr == ':') { backup(lexer); emit(lexer, LEXEME_VARIABLE_DEFAULT); advance_n(lexer, strlen(":")); return lex_variable_default; }
